package com.aigora.tutororchestrator.application.usecase;
import com.aigora.tutororchestrator.domain.model.*;import com.aigora.tutororchestrator.domain.valueobjects.*;import com.aigora.tutororchestrator.infrastructure.InMemoryLearningSessionRepository;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.junit.jupiter.api.Assertions.*;
class LearningSessionRecoveryCoordinatorTest { @Test void shouldIdentifyAwaitingAssessment(){var repo=new InMemoryLearningSessionRepository();var s=LearningSession.create(new LearningSessionId("s1"),new StudentId("u1"),Instant.EPOCH);s.start(new NodeId("n1"),new ExerciseId("e1"),new CommandId("start"),new CorrelationId("c"),new CausationId("x"),Instant.EPOCH);s.drainEvents();s.completeExercise(new ExerciseAttemptId("a1"),new ExerciseId("e1"),new CommandId("complete"),new CorrelationId("c"),new CausationId("x"),Instant.EPOCH);s.drainEvents();repo.insert(s);var coordinator=new LearningSessionRecoveryCoordinator(repo);assertEquals(RecoveryAction.REQUEST_ASSESSMENT,coordinator.actionFor(s.id()));assertEquals(1,coordinator.recoverableSessions().size());} }
